mapper.select:
select r.review_idx, r.reviewer_idx, max(u.user_name) as user_name, r.role, max(r.content)as content, max(r.created_at) as created_at, listagg(k.keyword_name,',') within group (order by k.keyword_name) as keywords from ( select review_coach_idx as review_idx,reviewer_idx,content,created_at,'COACH' as role from review_coach union all select review_class_idx as review_idx,reviewer_idx,content,created_at,'CLASS' as role from review_class ) r join users u on r.reviewer_idx = u.user_idx join ( select keyword_type,keyword_name from keyword
keyword_type=#{keyword_type}
) k on r.content like '%' || k.keyword_name || '%' group by r.review_idx,r.reviewer_idx,r.role order by created_at desc
